const content = `
  <div class="flexcol">
    <h3>Rerolling a Skill:</h3>
    <p>Please pick a skill to reroll from the buttons below.</p>
  </div>
`;

async function getAnswer() {
  return Dialog.wait({
    title: `${item.name} – Reroll a Skill`,
    content: content,
    buttons: {
      acr: {
        label: pf1.config.skills["acr"],
        callback: () => "acr",
      },
      clm: {
        label: pf1.config.skills["clm"],
        callback: () => "clm",
      },
      spl: {
        label: pf1.config.skills["spl"],
        callback: () => "spl",
      },
      ste: {
        label: pf1.config.skills["ste"],
        callback: () => "ste",
      },
      umd: {
        label: pf1.config.skills["umd"],
        callback: () => "umd",
      }
    },
    default: 'acr',
    close: () => null,
  },
  {
     height: "auto",
     width: 680,
  });
}

const answer = await getAnswer();
if(answer !== null) {
  actor.rollSkill(answer);
} else {
  ui.notifications.warn(`No answer was selected. Restoring use of "${item.name}".`);
  await item.update({"system.uses.value": 1 });
}

const content = `
  <div class="flexcol">
    <h3>Rerolling a Saving Throw:</h3>
    <p>Please pick a saving throw to reroll from the buttons below.</p>
  </div>
`;

const labels = [game.i18n.localize("PF1.SavingThrowFort"), game.i18n.localize("PF1.SavingThrowRef"), game.i18n.localize("PF1.SavingThrowWill")];

async function getAnswer() {
  return Dialog.wait({
    title: `${item.name} – Reroll a Saving Throw`,
    content: content,
    buttons: {
      fort: {
        label: labels[0],
        callback: () => "fort",
      },
      ref: {
        label: labels[1],
        callback: () => "ref",
      },
      will: {
        label: labels[2],
        callback: () => "will",
      }
    },
    default: 'fort',
    close: () => null,
  },
  {
     height: "auto",
     width: 680,
  });
}

const answer = await getAnswer();
if(answer !== null) {
  actor.rollSavingThrow(answer);
} else {
  ui.notifications.warn(`No answer was selected. Restoring use of "${item.name}".`);
  await item.update({"system.uses.value": 1 });
}

const content = `
<div class="flexcol">
<label>
  <input type="radio" name="skillId" value="khi">
  ${pf1.config.skills.khi}
</label>
<label>
  <input type="radio" name="skillId" value="kar">
  ${pf1.config.skills.kar}
</label>
</div>
<hr>
`;

const skillId = await Dialog.wait({
  title: `Select Skill for ${item.name}`,
  content,
  buttons: {
    ok: {
      label: "Select",
      callback: ([html]) => html.querySelector("input:checked")?.value ?? null,
    }
  },
  close: () => null,
},
{
  width: 260,
  rejectClose: false,
});

if (!skillId) {
  shared.reject = true;
  return;
}

actor.rollSkill(skillId, { bonus: `15[${item.name}]` });
